    let _context = diagnostics::invocation_scope();
    let operation = || {
        attempt::run(usize::MAX, || {
            let mut owner = Receiver::acquire()?;
            match constructor_test_typed_defaults::default_expr(&Type::I64, &[], false, &mut owner) {
                Ok(value) => {
                    drop(value);
                    drop(owner);
                    Ok(())
