//! Explicit original receiver authority; old One/Many helpers remain independent.
use super::receiving::{CoreFailure, Receiver, Setup};
use crate::diagnostic::Diagnostic;
#[derive(Debug)]
#[allow(
    clippy::large_enum_variant,
    reason = "selected diagnostic stays inline after refusal"
)]
pub(in crate::workspace_graph) enum Failure {
    One(Diagnostic),
    Many(Vec<Diagnostic>),
    Setup(Setup),
}
impl Failure {
    pub(in crate::workspace_graph) fn one(diagnostic: Diagnostic) -> Self {
        Self::One(diagnostic)
    }
}
impl From<Vec<Diagnostic>> for Failure {
    fn from(report: Vec<Diagnostic>) -> Self {
        Self::Many(report)
    }
}
impl From<Setup> for Failure {
    fn from(failure: Setup) -> Self {
        Self::Setup(failure)
    }
}
impl From<Diagnostic> for Failure {
    fn from(primary: Diagnostic) -> Self {
        Self::One(primary)
    }
}
pub(in crate::workspace_graph) fn construct_transient_core<'a>(
    program: &'a crate::ast::Program,
    authored: &'a std::collections::BTreeMap<&'a str, super::super::AuthoredDeclaration<'a>>,
    programs: &'a [crate::ast::Program],
    registry: &super::super::expected_projection::private_layout::registry::LayoutRegistry<'_>,
    core: &mut super::super::expected_projection::CoreProviderProofs<'a>,
    owner: &mut Receiver,
) -> Result<super::super::expected_projection::borrowed_leaf::Input<'a>, Failure> {
    use super::super::expected_projection::{borrowed_imports, borrowed_leaf};
    use borrowed_leaf::Input;
    owner.entry::<Input<'a>>()?;
    if borrowed_leaf::eligible(program) {
        borrowed_leaf::construct(program)
            .map(Input::Borrowed)
            .map_err(Failure::from)
    } else if borrowed_imports::eligible(program, authored, programs) {
        borrowed_imports::typed::construct_using(
            program,
            authored,
            programs,
            registry,
            Some(core),
            owner,
        )
        .map(Input::Borrowed)
    } else {
        // Explicit legacy dependency: its Vec producers are not recertified.
        Input::construct_transient_core(program, authored, programs, registry, core)
            .map_err(Failure::from)
    }
}
impl Receiver {
    /// Semantic selection precedes a secondary receiving/sticky association.
    pub(in crate::workspace_graph) fn receive_typed(self, failure: Failure) -> CoreFailure {
        match failure {
            Failure::One(primary) => self.receive(super::Failure::One(primary)),
            Failure::Many(report) => self.receive(super::Failure::Many(report)),
            Failure::Setup(refusal) => {
                drop(self);
                CoreFailure::Setup(refusal)
            }
        }
    }
}

//! Complete overlay walk; only default refusal custody changes.
use super::{
    AuthoredDeclaration, LayoutRegistry, StructuralCost, alias_clone, ast_function_cost,
    ast_function_signature_cost, ast_type_declaration_cost, budgeted_format, directory, eligible,
    graph_error, import_stub, iterative, pay_default_teardown, pay_signature, pay_teardown,
    pay_teardown_minimum, pay_type, refusal, type_rewrite,
};
use crate::ast::program_source::{SyntheticProgramView, generated_roots::GeneratedRoots};
use crate::ast::{Expr, ExprKind, Function, ModuleUseKind, Program, Type, TypeDeclaration};
use crate::workspace_graph::constructor_failure::{receiving::Receiver, typed::Failure};
use std::collections::BTreeMap;

pub(in crate::workspace_graph) fn construct_using<'p, 'a>(
    program: &'p Program,
    authored: &'a BTreeMap<&'a str, AuthoredDeclaration<'a>>,
    programs: &'a [Program],
    registry: &LayoutRegistry<'_>,
    core: Option<&mut import_stub::core_proofs::CoreProviderProofs<'a>>,
    owner: &mut Receiver,
) -> Result<SyntheticProgramView<'p>, Failure> {
    owner.entry::<SyntheticProgramView<'p>>()?;
    owner.reserve(0)?;
    if !eligible(program, authored, programs) {
        return Err(Failure::one(graph_error(
            "SPX-G173",
            "imported borrowed projection requires the owned route",
        )));
    }
    let layout = registry.get(program, authored, programs)?;
    let explicit = program
        .module_uses
        .iter()
        .filter(|import| import.kind == ModuleUseKind::Type)
        .count();
    let type_count = explicit
        .checked_add(layout.entries.len())
        .ok_or_else(refusal)?;
    let recursive = iterative(program, authored);
    if recursive {
        pay_teardown_minimum()?;
    }
    let mut roots = if recursive {
        GeneratedRoots::iterative(directory::<TypeDeclaration>(type_count)?, Vec::new())
    } else {
        GeneratedRoots::plain(directory::<TypeDeclaration>(type_count)?, Vec::new())
    };
    let types = &mut roots.types;
    for import in program
        .module_uses
        .iter()
        .filter(|import| import.kind == ModuleUseKind::Type)
    {
        let target = &authored[import.persistent_id.as_str()];
        let declaration = target.ty.expect("validated type target");
        pay_type(declaration)?;
        if recursive {
            let mut cost = StructuralCost::raw_ast(true).with_inline_values(true);
            ast_type_declaration_cost(declaration, &mut cost)?;
            pay_teardown(&cost)?;
        }
        types.push(alias_clone::type_payload(declaration));
        let copy = types.last_mut().expect("inserted type");
        copy.name = owner.text(&import.alias)?;
        owner.reserve(0)?;
        super::super::super::generic_type_import::rewrite_declaration_with_layout(
            copy,
            target.module,
            program,
            programs,
            Some(&layout),
        )?;
    }
    // Preserve the independent closure's exact order after explicit aliases.
    for entry in &layout.entries {
        pay_type(entry.declaration)?;
        if recursive {
            let mut cost = StructuralCost::raw_ast(true).with_inline_values(true);
            ast_type_declaration_cost(entry.declaration, &mut cost)?;
            pay_teardown(&cost)?;
        }
        types.push(alias_clone::type_payload(entry.declaration));
        let copy = types.last_mut().expect("inserted private type");
        copy.name = owner.text(&entry.alias)?;
        owner.reserve(0)?;
        super::super::super::generic_type_import::rewrite_declaration_with_layout(
            copy,
            entry.module,
            program,
            programs,
            Some(&layout),
        )?;
    }
    let all_count = program
        .types
        .len()
        .checked_add(types.len())
        .ok_or_else(refusal)?;
    let mut type_index = directory::<(&str, &TypeDeclaration)>(all_count)?;
    type_index.extend(
        program
            .types
            .iter()
            .chain(types.iter())
            .map(|declaration| (declaration.name.as_str(), declaration)),
    );
    type_index.sort_unstable_by(|a, b| a.0.cmp(b.0));
    if type_index.windows(2).any(|items| items[0].0 == items[1].0) {
        return Err(Failure::one(graph_error(
            "SPX-G173",
            "synthetic workspace type-name index is not unique",
        )));
    }
    let needs_main = !program
        .functions
        .iter()
        .any(|function| function.name == "main")
        && !program
            .module_uses
            .iter()
            .any(|import| import.kind == ModuleUseKind::Function && import.alias == "main");
    let imports = program
        .module_uses
        .iter()
        .filter(|import| import.kind == ModuleUseKind::Function)
        .count();
    roots.functions = directory::<Function>(
        imports
            .checked_add(usize::from(needs_main))
            .ok_or_else(refusal)?,
    )?;
    let functions = &mut roots.functions;
    let mut byte_proofs =
        import_stub::core_proofs::Phase::new(authored, programs, core).map_err(Failure::one)?;
    for import in program
        .module_uses
        .iter()
        .filter(|import| import.kind == ModuleUseKind::Function)
    {
        let target = &authored[import.persistent_id.as_str()];
        let original = target.function.expect("validated function target");
        let retain_body = programs
            .iter()
            .find(|provider| provider.module == target.module)
            .is_some_and(|provider| {
                crate::vec_ops::source_wrapper(provider, original).is_some()
                    || crate::box_ops::source_wrapper(provider, original).is_some()
            });
        if retain_body {
            let mut cost = StructuralCost::raw_ast(true).with_inline_values(true);
            ast_function_cost(original, &mut cost)?;
            owner.reserve(cost.total)?;
            pay_teardown(&cost)?;
        } else {
            pay_signature(original)?;
            if recursive {
                let mut cost = StructuralCost::raw_ast(true).with_inline_values(true);
                ast_function_signature_cost(original, &mut cost)?;
                pay_teardown(&cost)?;
            }
        }
        let function = if retain_body {
            alias_clone::retained_function(original, &import.alias)
        } else {
            alias_clone::signature_function(original, &import.alias)
        };
        functions.push(function);
        owner.reserve(0)?;
        if retain_body {
            continue;
        }
        let function = functions.last_mut().expect("inserted signature");
        for param in &mut function.params {
            type_rewrite::rewrite_with_layout(
                &mut param.ty,
                target.module,
                program,
                programs,
                Some(&layout),
            )?;
        }
        type_rewrite::rewrite_with_layout(
            &mut function.return_type,
            target.module,
            program,
            programs,
            Some(&layout),
        )?;
        if recursive {
            pay_default_teardown(&function.return_type, &type_index)?;
        }
        function.body = import_stub::typed::default_expr(
            function,
            &type_index,
            super::super::super::owned_function_import::admitted_with_layout(
                program, target, authored, programs, &layout,
            ),
            byte_proofs
                .get()
                .map_err(Failure::one)?
                .authorized(original, target.module)
                .map_err(Failure::one)?,
            owner,
        )?;
    }
    // Same old rule also recognizes an imported alias named main.
    if needs_main && !functions.iter().any(|function| function.name == "main") {
        owner.reserve(std::mem::size_of::<Expr>())?;
        let stable_id =
            budgeted_format(format_args!("workspace.synthetic.main.{}", program.module));
        owner.reserve(0)?;
        let name = owner.text("main")?;
        functions.push(Function {
            stable_id,
            explicit_id: true,
            name,
            name_span: crate::ast::Span::default(),
            type_parameters: Vec::new(),
            params: Vec::new(),
            return_type: Type::I64,
            effects: Vec::new(),
            yields: None,
            follows: None,
            requires: Vec::new(),
            ensures: Vec::new(),
            body: Expr {
                kind: ExprKind::Int(0),
                span: crate::ast::Span::default(),
            },
            span: crate::ast::Span::default(),
        });
        owner.reserve(0)?;
    }
    drop(type_index);
    // Infallible bounded string helpers record refusal and return empty text.
    // A generated view must never publish that partial construction as success.
    owner.reserve(0)?;
    let result = SyntheticProgramView::with_generated_owner(program, roots).ok_or_else(refusal)?;
    byte_proofs.complete().map_err(Failure::one)?;
    Ok(result)
}

//! Same complete default evaluation with explicit internal error custody.
use super::typed_fields as field_directory;
use super::{
    Span, StructuralCost, Type, TypeDeclaration, TypeDeclarationKind, checked_builder_sum,
};
use crate::ast::{Expr, ExprKind};
use crate::diagnostic::Diagnostic;
use crate::workspace_graph::constructor_failure::{receiving::Receiver, typed::Failure};
pub(in crate::workspace_graph) fn default_expr(
    ty: &Type,
    declarations: &[(&str, &TypeDeclaration)],
    allow_owned: bool,
    owner: &mut Receiver,
) -> Result<Expr, Failure> {
    owner.entry::<Expr>()?;
    owner.reserve(std::mem::size_of::<Expr>())?;
    let span = Span::default();
    let kind = match ty {
        Type::Never => {
            return Err(Failure::one(Diagnostic::io_static(
                "SPX-G172",
                "compiler-only completion marker has no default value",
            )));
        }
        ty if allow_owned
            && super::super::type_rewrite::default_vector_element(ty, declarations).is_some() =>
        {
            let element = super::super::type_rewrite::default_vector_element(ty, declarations)
                .expect("closed vector default");
            let mut cost = StructuralCost::new();
            super::super::declaration_cost::ast_type_cost(element, &mut cost)?;
            owner.reserve(checked_builder_sum(
                cost.total,
                std::mem::size_of::<Expr>() + crate::vec_ops::WITH_CAPACITY_NAME.len(),
            )?)?;
            ExprKind::Call {
                name: owner.text(crate::vec_ops::WITH_CAPACITY_NAME)?,
                type_arguments: vec![element.clone()],
                args: vec![Expr {
                    kind: ExprKind::Usize(0),
                    span,
                }],
            }
        }
        ty if allow_owned && crate::map_ops::ast_collection(ty) => {
            let (name, arguments) = collection_constructor(ty);
            owner.reserve(std::mem::size_of::<Expr>() + std::mem::size_of_val(arguments))?;
            ExprKind::Call {
                name: owner.text(name)?,
                type_arguments: arguments.to_vec(),
                args: vec![Expr {
                    kind: ExprKind::Usize(0),
                    span,
                }],
            }
        }
        Type::I64 => ExprKind::Int(0),
        Type::I32 => ExprKind::Int32(0),
        Type::Char => ExprKind::Char(0),
        Type::U8 => ExprKind::Uint8(0),
        Type::Usize => ExprKind::Usize(0),
        Type::F32 => ExprKind::Float32(0),
        Type::F64 => ExprKind::Float64(0),
        Type::Bool => ExprKind::Bool(false),
        Type::String => ExprKind::String(String::new()),
        Type::Str => {
            return Err(Failure::one(Diagnostic::io_static(
                "SPX-G173",
                "borrowed `str` has no synthesizable workspace default",
            )));
        }
        Type::SliceU8 | Type::StringMap => {
            return Err(Failure::one(Diagnostic::io_static(
                "SPX-G173",
                "borrowed `Slice<u8>` has no synthesizable workspace default",
            )));
        }
        Type::Bytes if allow_owned => {
            owner.reserve(std::mem::size_of::<Expr>())?;
            ExprKind::Call {
                name: owner.text(crate::byte_ops::ZEROED_NAME)?,
                type_arguments: Vec::new(),
                args: vec![Expr {
                    kind: ExprKind::Usize(0),
                    span,
                }],
            }
        }
        Type::ArrayU8(_)
        | Type::Bytes
        | Type::OnceFunction
        | Type::OnceFunctionI64
        | Type::OnceFunctionI64Pair
        | Type::MutFunctionI64
        | Type::Function { .. } => {
            return Err(Failure::one(Diagnostic::io_static(
                "SPX-G173",
                "internal byte-data types have no synthesizable workspace default",
            )));
        }
        Type::Named { name, arguments } if arguments.is_empty() => {
            let declaration = declarations
                .binary_search_by_key(&name.as_str(), |(name, _)| *name)
                .map(|index| declarations[index].1)
                .map_err(|_| {
                    Failure::one(Diagnostic::io_static(
                        "SPX-G173",
                        "default imported type lookup disagrees",
                    ))
                })?;
            match &declaration.kind {
                TypeDeclarationKind::Record { fields }
                | TypeDeclarationKind::Class { fields, .. } => ExprKind::ConstructRecord {
                    type_name: owner.text(name)?,
                    type_span: span,
                    type_arguments: Vec::new(),
                    fields: field_directory::build(fields, declarations, allow_owned, owner)?,
                },
                TypeDeclarationKind::Variant { cases } => {
                    let case = cases.first().ok_or_else(|| {
                        Failure::one(Diagnostic::io_static(
                            "SPX-G172",
                            "imported Copy variant has no case",
                        ))
                    })?;
                    ExprKind::ConstructVariant {
                        type_name: owner.text(name)?,
                        type_span: span,
                        type_arguments: Vec::new(),
                        case_name: owner.text(&case.name)?,
                        case_span: span,
                        fields: field_directory::build(
                            &case.fields,
                            declarations,
                            allow_owned,
                            owner,
                        )?,
                    }
                }
                TypeDeclarationKind::Resource { .. } => {
                    return Err(Failure::one(Diagnostic::io_static(
                        "SPX-G172",
                        "resource return is not admitted",
                    )));
                }
            }
        }
        Type::Named { .. } => {
            return Err(Failure::one(Diagnostic::io_static(
                "SPX-G172",
                "generic return is not admitted",
            )));
        }
    };
    Ok(Expr { kind, span })
}

